solution:
#include <iostream>

void repartir(int montant, int personnes, int& part, int& reste) {
    part = montant / personnes;
    reste = montant % personnes;
}

int main() {
    int montant, personnes;
    std::cin >> montant >> personnes;
    if (personnes <= 0) {
        std::cout << "Nombre de personnes invalide\n";
        return 0;
    }
    int part, reste;
    repartir(montant, personnes, part, reste);
    std::cout << "Part : " << part << " FCFA\n";
    std::cout << "Reste : " << reste << " FCFA\n";
    return 0;
}
